42	/**
43	 * Mostly used as a facade for all Petclinic controllers
44	 * Also a placeholder for @Transactional and @Cacheable annotations
45	 *
46	 * @author Michael Isvy
47	 * @author Vitaliy Fedoriv
48	 */
49	@Service
50	public class ClinicServiceImpl implements ClinicService {
51	
52	    private final PetRepository petRepository;
53	    private final VetRepository vetRepository;
54	    private final OwnerRepository ownerRepository;
55	    private final VisitRepository visitRepository;
56	    private final SpecialtyRepository specialtyRepository;
57	    private final PetTypeRepository petTypeRepository;
58	    private final OwnerAuditLogger ownerAuditLogger;
59	
60	    public ClinicServiceImpl(
61	        PetRepository petRepository,
62	        VetRepository vetRepository,
63	        OwnerRepository ownerRepository,
64	        VisitRepository visitRepository,
65	        SpecialtyRepository specialtyRepository,
66	        PetTypeRepository petTypeRepository,
67	        OwnerAuditLogger ownerAuditLogger) {
68	        this.petRepository = petRepository;
69	        this.vetRepository = vetRepository;
70	        this.ownerRepository = ownerRepository;
71	        this.visitRepository = visitRepository;
72	        this.specialtyRepository = specialtyRepository;
73	        this.petTypeRepository = petTypeRepository;
74	        this.ownerAuditLogger = ownerAuditLogger;
75	    }
76	
77	    @Override
78	    @Transactional(readOnly = true)
79	    public Collection<Pet> findAllPets() throws DataAccessException {
80	        return petRepository.findAll();
81	    }
82	
83	    @Override
84	    @Transactional(readOnly = true)
85	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
86	        return petRepository.findAll(pageable);
87	    }
