137	    @Override
138	    @Transactional(readOnly = true)
139	    public Collection<Owner> findAllOwners() throws DataAccessException {
140	        return ownerRepository.findAll();
141	    }
142	
143	    @Override
144	    @Transactional(readOnly = true)
145	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
