238	    @Override
239	    @Transactional(readOnly = true)
240	    public Collection<Vet> findVets() throws DataAccessException {
241	        return vetRepository.findAll();
242	    }
243	
244	    /**
245	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
246	     * already reached this many owners is rejected as a conflict.
247	     */
248	    static final int MAX_OWNERS_PER_CITY = 50;
249	
250	    /**
251	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
252	     * already reached this many registrations is rejected as a rate-limit violation.
253	     */
254	    static final int MAX_OWNERS_PER_DAY = 100;
255	
256	    /**
257	     * Number of owners that must already have registered on a day before a new registration is
258	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
259	     * value, the new owner carries {@code bulkSignupWarning == true}.
260	     */
261	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
262	
263	    @Override
264	    @Transactional
265	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
266	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
267	            throw new DisposableEmailDomainException(owner.getEmail());
268	        }
269	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
270	        rejectIdentityCollision(owner);
271	        List<Owner> householdMembers = findHouseholdMembers(owner);
272	        if (!householdMembers.isEmpty() && !sharesHousehold) {
273	            throw new HouseholdDuplicateException(owner.getHouseholdId());
274	        }
275	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
276	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
277	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
278	        }
279	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
280	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
281	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
282	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
283	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
284	        }
285	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
286	        flagPossibleDuplicate(owner, householdMembers, sharesHousehold);
287	        owner.setNamesakeCount(countNamesakes(owner));
288	        owner.setHouseholdSize(householdMembers.size() + 1);
289	        owner.setCustomerCode(CustomerCodeGenerator.format(
290	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
291	            owner.getTelephone(), owner.getLastName()));
292	        ownerRepository.save(owner);
293	        ownerAuditLogger.ownerCreated(owner);
294	        return owner.getHouseholdId();
295	    }
296	
297	    /**
298	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
299	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
300	     * key component (normalized telephone, email and household identifier) is a duplicate.
301	     */
302	    private void rejectIdentityCollision(Owner owner) {
303	        String identityKey = OwnerIdentityKey.of(owner);
304	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
305	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
306	        if (collides) {
307	            throw new DuplicateOwnerException(identityKey);
308	        }
309	    }
310	
311	    /**
312	     * Flag the new owner as a possible (soft) duplicate of an existing household member carrying a
313	     * different telephone. The new owner is still created; {@code possibleDuplicate} is set to
314	     * whether such a match exists and {@code possibleDuplicateOf} to the matching owner's id (the
315	     * lowest when several match), or {@code null} when there is no match.
316	     *
317	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
318	     * member rather than a suspected duplicate, so it is never flagged.
319	     */
320	    private void flagPossibleDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
321	        Owner match = sharesHousehold ? null : householdMembers.stream()
322	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
323	            .min(Comparator.comparingInt(Owner::getId))
324	            .orElse(null);
325	        owner.setPossibleDuplicate(match != null);
326	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
327	    }
328	
329	    @Override
330	    @Transactional
331	    public void saveOwner(Owner owner) throws DataAccessException {
332	        ownerRepository.save(owner);
333	    }
334	
335	    /**
336	     * Count the owners that already exist sharing this owner's first name and last name, compared
337	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
338	     */
339	    private int countNamesakes(Owner owner) {
340	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
341	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
342	            .count();
343	    }
344	
345	    /**
346	     * Find the existing owners that already share this owner's household, i.e. that derive the same
347	     * computed {@code householdId} (the same last name and postcode). An owner without a postcode
348	     * has no household peers.
349	     */
350	    private List<Owner> findHouseholdMembers(Owner owner) {
351	        if (owner.getPostcode() == null) {
352	            return List.of();
353	        }
354	        String householdId = owner.getHouseholdId();
355	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
356	            .filter(existing -> householdId.equals(
357	                HouseholdIdGenerator.generate(existing.getLastName(), existing.getPostcode())))
358	            .toList();
359	    }
360	
361	    @Override
362	    @Transactional(readOnly = true)
363	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
364	        return ownerRepository.findByLastName(lastName);
365	    }
366	
367	    @Override
368	    @Transactional(readOnly = true)
369	    public Collection<Visit> findVisitsByPetId(int petId) {
370	        return visitRepository.findByPetId(petId);
371	    }
372	
373	    @Override
374	    @Transactional(readOnly = true)
375	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
376	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
377	    }
378	
379	    private <T> T findEntityById(Supplier<T> supplier) {
380	        try {
381	            return supplier.get();
382	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
383	            // Just ignore not found exceptions for Jdbc/Jpa realization
384	            return null;
385	        }
386	    }
387	
388	}
