277			Map<String, Object> ownerParams = new HashMap<>();
278			ownerParams.put("id", owner.getId());
279	        List<Pet> pets = owner.getPets();
280	        // cascade delete pets
281	        for (Pet pet : pets){
282	        	Map<String, Object> petParams = new HashMap<>();
283	        	petParams.put("id", pet.getId());
284	        	// cascade delete visits
285	        	List<Visit> visits = pet.getVisits();
286	            for (Visit visit : visits){
287	            	Map<String, Object> visitParams = new HashMap<>();
288	            	visitParams.put("id", visit.getId());
289	            	this.namedParameterJdbcTemplate.update("DELETE FROM visits WHERE id=:id", visitParams);
290	            }
291	            this.namedParameterJdbcTemplate.update("DELETE FROM pets WHERE id=:id", petParams);
292	        }
293	        this.namedParameterJdbcTemplate.update("DELETE FROM owners WHERE id=:id", ownerParams);
294		}
